nta.declaration:
// 061 T030 — timed model of the supervision loop (contracts/supervision.md,
// SC-003, FR-040). Time unit = 100 ms so the shipped defaults stay small ints.
//
//   ping_interval 5 s   ping_timeout 3 s   backoff_initial 1 s
//   backoff_max  30 s   restore bound 10 s crash_threshold 3 (DEF-F2)
//
// The supervisor is the engine's one wire client (FR-002): it pings on a
// timer; a missing ack within PT (or no up-signal within the boot window)
// counts as death; each death increments the crash count; at THRESHOLD the
// DEF-F2 taxonomy stops the loop (modelled as the absorbing Stopped state —
// no silent restart loops). gdead measures time since the MOST RECENT death
// (the engine resets it on every crash edge), so the bound query is per
// recovery cycle, matching SC-003's "detect → restart → restore" reading.

const int PI       = 50;   // ping_interval  (5.0 s)
const int PT       = 30;   // ping_timeout   (3.0 s)
const int BI       = 10;   // backoff_initial (1.0 s)
const int BMAX     = 300;  // backoff_max    (30.0 s)
const int RESTORE  = 100;  // restore upper bound (10.0 s)
const int THRESHOLD = 3;   // crash_threshold (DEF-F2)

// Boot-confirmation window the supervisor grants a replacement engine.
const int BOOTWIN  = PI + PT + RESTORE;

// SC-003 detect→restart→restore bound, per recovery cycle. The worst case is
// a crash DURING boot: the supervisor may sit out the remaining boot window
// (<= BOOTWIN) before detecting, then backoff (<= BMAX), then restore
// (<= RESTORE).
const int BOUND = BOOTWIN + BMAX + RESTORE;

broadcast chan ping, ack, restart, up, crash;
clock gdead;                       // time since the most recent death
int[0,THRESHOLD] crashes = 0;      // deaths detected (monotone; DEF-F2)
